158: test("T141 — nine resource states, each distinguishable without colour", () => {
159:   const chip = read("StatusChip.jsx");
160:   const styles = surfaces();
161:   const states = ["loading", "ready", "empty", "stale", "offline", "unconfigured", "unavailable", "disabled", "error"];
162: 
163:   for (const state of states) {
164:     assert.ok(chip.includes(`${state}:`), `RESOURCE_STATES is missing ${state}`);
165:     assert.match(styles, new RegExp(`\.resource-state\.is-${state}`), `${state} has no visual treatment`);
166:   }
167: 
168:   // The three pairs that must never look the same, because collapsing them is
169:   // how the app would lie. Each pair differs by something other than colour.
170:   const treatment = state => {
171:     const at = styles.indexOf(`.resource-state.is-${state} {`);
172:     return styles.slice(at, styles.indexOf("}", at));
173:   };
174:   assert.notEqual(treatment("empty"), treatment("loading"));
175:   assert.match(styles, /\.resource-state\.is-empty > i \{ display: none; \}/, "empty shows no dot at all");
176:   assert.match(styles, /\.resource-state\.is-loading > i \{ animation:/, "loading is the state about time passing");
177:   assert.match(treatment("unavailable"), /border-style: dotted/);
178:   assert.match(treatment("offline"), /border-style: dashed/);
179:   assert.notEqual(treatment("stale"), treatment("ready"));
180: 
181:   // Semantics, not just paint: an error interrupts, a pending read is busy.
182:   assert.match(chip, /role=\{spec\.alert \? "alert" : "status"\}/);
183:   assert.match(chip, /aria-busy=\{spec\.busy \|\| undefined\}/);
184:   assert.match(chip, /error:\s*\{ tone: "critical",[^}]*alert: true \}/);
185:   assert.match(chip, /loading:\s*\{ tone: "neutral",[^}]*busy: true \}/);
